# catch different error types
try:
    items = [1, 2, 3]
    print(items[10])
except IndexError:
    print("that position doesn't exist")

try:
    result = 10 / 2
except ZeroDivisionError:
    print("can't divide by zero")
else:
    print(f"result: {result}")   # only if no error
finally:
    print("this always runs")

def divide(a, b):
    if b == 0:
        raise ValueError("can't divide by zero")
    return a / b

try:
    print(divide(10, 2))   # 5.0
    print(divide(10, 0))   # raises an error
except ValueError as e:
    print(f"Error: {e}")
